insert into public.opportunities (id, title, org, descr, category, mode, cost, grade, eligibility, deadline, featured, published, url, tags, last_verified) values
('isef', 'Regeneron ISEF', 'Society for Science', 'The world’s largest international pre-college science competition. Finalists are judged by doctoral-level scientists. The finals are held in a host city each year, and a virtual fair lets people view projects.', 'Competitions', 'In person', 'Not stated', 'High school students (grades not stated)', 'Students qualify by winning at a Society-affiliated local, regional, state or national science fair.', null, true, true, 'https://www.societyforscience.org/isef/', array['science','research']::text[], '2026-10-11'),
('rsi', 'Research Science Institute (RSI)', 'Center for Excellence in Education', 'A summer science and engineering program that pairs on-campus STEM classes with a five-week research internship under expert mentors. Held at MIT, and for 2027 it expands to Stanford for 50 scholars.', 'Research', 'In person', 'Free', 'High school juniors (seniors are not eligible)', 'High school juniors. The page states the program is cost-free to students.', 'Dec 11, 2026, 11:59pm (RSI 2027)', true, true, 'https://www.cee.org/research-science-institute', array['research','science']::text[], '2026-10-11'),
('primes', 'MIT PRIMES', 'MIT Mathematics', 'A year-long research program in mathematics, engineering and science for high school students, with four sections. The page describes all sections as free.', 'Research', 'Hybrid', 'Free', 'Grades 10-11 (sophomores and juniors)', 'MIT PRIMES is for Greater Boston students (in person). PRIMES-USA is for students elsewhere in the U.S. (remote). Yulia’s Dream is for students from Ukraine. Check the official page for who can apply.', 'Nov 2, 2026 (PRIMES, PRIMES-USA, PRIMES Circle)', false, true, 'https://math.mit.edu/research/highschool/primes/', array['math','research','science']::text[], '2026-10-11'),
('cs50x', 'CS50x: Intro to Computer Science', 'Harvard University', 'Harvard’s introductory computer science course: computational thinking, algorithms and data structures, starting in C and moving through Python, SQL and web programming before a final project.', 'Courses', 'Online', 'Free', 'Anyone, with or without programming experience', 'Open to everyone. Submitting problem sets for feedback requires an edX account. Costs of optional certificates are not stated on the page.', null, false, true, 'https://cs50.harvard.edu/x/', array['coding']::text[], '2026-10-11'),
('ocw', 'MIT OpenCourseWare', 'Massachusetts Institute of Technology', 'A free web publication of virtually all MIT course content that you can work through at your own pace.', 'Courses', 'Online', 'Free', 'Anyone in the world', 'No registration required for the free lecture notes, exams and videos.', null, false, true, 'https://ocw.mit.edu/', array['science','coding','math']::text[], '2026-10-11'),
('khan', 'Khan Academy', 'Khan Academy', 'A nonprofit offering 840+ free courses in core academic subjects, with apps on the Apple App Store and Google Play.', 'Courses', 'Online', 'Free', 'K-12 and early college', 'For students, teachers and parents.', null, false, true, 'https://www.khanacademy.org/about', array['math','science']::text[], '2026-10-11'),
('kaggle-learn', 'Kaggle Learn', 'Kaggle', 'Short tutorials for building practical data skills, including Python, data visualization and Pandas.', 'Courses', 'Online', 'Free', 'Not stated', 'Not stated', null, false, true, 'https://www.kaggle.com/learn', array['coding']::text[], '2026-10-11'),
('freecodecamp', 'freeCodeCamp', 'freeCodeCamp.org', 'The site describes itself as a place to learn to code for free.', 'Courses', 'Online', 'Free', 'Not stated', 'Not stated', null, false, true, 'https://www.freecodecamp.org/', array['coding']::text[], '2026-10-11'),
('chevening', 'Chevening Scholarships', 'Chevening', 'Fully funded scholarships for outstanding emerging leaders from around the world to study a one-year master’s degree in the UK. What the funding covers is not stated on this page.', 'Scholarships', 'In person', 'Funded', 'One-year master’s degrees in the UK', 'See the official “Who can apply?” page. Eligibility is not listed on the scholarships page.', null, false, true, 'https://www.chevening.org/scholarships/', array['entrepreneurship']::text[], '2026-10-11'),
('fulbright', 'Fulbright Foreign Student Program', 'Fulbright Program', 'Grants that let graduate students, young professionals and artists from abroad study or conduct research in the United States. What the grants cover is not stated on this page.', 'Scholarships', 'In person', 'Funded', 'Graduate students, young professionals and artists from abroad', 'Non-U.S. citizens apply through the Fulbright Commission, Foundation or U.S. Embassy in their home country.', null, false, true, 'https://foreign.fulbrightonline.org/', array['research']::text[], '2026-10-11'),
('daad', 'DAAD Scholarships (Germany)', 'DAAD', 'The German Academic Exchange Service is one of the organizations where international students can apply for a scholarship to study in Germany.', 'Scholarships', 'In person', 'Varies', 'Not stated', 'Levels of study are not stated on this page. Use the DAAD scholarship database to find matching offers.', null, false, true, 'https://www.daad.de/en/study-and-research-in-germany/scholarships/', array['languages']::text[], '2026-10-11'),
('unv', 'United Nations Volunteers', 'UN Volunteers (UNV)', 'A United Nations programme that mobilizes volunteers in 150 countries. The site lists online volunteering as an option.', 'Volunteering', 'Hybrid', 'Not stated', 'Not stated', 'A minimum age is not stated on the homepage. Volunteers register in the Talent Pool. Check the official page for requirements.', null, false, true, 'https://www.unv.org/', array['volunteering']::text[], '2026-10-11'),
('ioi', 'International Olympiad in Informatics (IOI)', 'IOI', 'An international computer science competition. Over two days, students compete individually on programming and algorithmic tasks. UNESCO and IFIP are patrons.', 'Competitions', 'Not stated', 'Not stated', 'Secondary school students (up to four per country)', 'How students qualify is not stated on the homepage. Ask your national olympiad or team.', null, false, true, 'https://ioinformatics.org/', array['coding','math']::text[], '2026-10-11'),
('imo', 'International Mathematical Olympiad (IMO)', 'IMO', 'The official site of the International Mathematical Olympiad. It lists upcoming editions, including IMO 2026 in Shanghai and IMO 2027 in Budapest, Hungary.', 'Competitions', 'Not stated', 'Not stated', 'Not stated', 'Age, school level and how students qualify are not stated on the homepage. Check with your national team.', null, false, true, 'https://www.imo-official.org/', array['math']::text[], '2026-10-11'),
('gsoc', 'Google Summer of Code', 'Google', 'A global online program that brings new contributors into open source software. You work on a 12+ week programming project with an open source organization, guided by mentors.', 'Activities', 'Online', 'Not stated', 'Not stated', 'Age and student status are not stated on the homepage. Check the official eligibility pages before planning on it.', null, false, true, 'https://summerofcode.withgoogle.com/', array['coding']::text[], '2026-10-11'),
('intaward', 'Duke of Edinburgh’s International Award', 'The International Award Foundation', 'A non-formal education framework available in more than 130 countries that recognises achievements outside of school. Participants develop their interests and skills while making a difference in their communities.', 'Activities', 'Not stated', 'Not stated', 'Ages 14 to 24', 'Open to young people aged 14 to 24 regardless of background, location, culture or ability.', null, false, true, 'https://www.intaward.org/', array['volunteering']::text[], '2026-10-11'),
('arc', 'Arab Reading Challenge', 'Arab Reading Challenge', 'A reading initiative launched by Sheikh Mohammed bin Rashid Al Maktoum. Students read books outside their curriculum and write a one-page summary of each, moving through five stages of 10 books each, 50 books in one school year.', 'Competitions', 'Not stated', 'Not stated', 'Students in the Arab world (ages and grades not stated)', 'Students register through their schools and supervisors. The page does not list participating countries on the homepage.', null, true, true, 'https://www.arabreadingchallenge.com/', array['arab','languages']::text[], '2026-10-11'),
('edraak', 'Edraak: online courses in Arabic', 'Edraak (Queen Rania Foundation)', 'An Arabic open online course (MOOC) platform from the Queen Rania Foundation. Categories include Career Readiness, Technology, Personal Development, Business and Entrepreneurship, and Languages.', 'Courses', 'Online', 'Not stated', 'Not stated', 'The page offers a free registration button. It does not say whether every course is free.', null, false, true, 'https://www.edraak.org/en/', array['arab','entrepreneurship','languages']::text[], '2026-10-11'),
('rwaq', 'Rwaq: Arabic open education', 'Arawaq Al-Ma’rifa Association', 'Describes itself as the Arabic platform for open education, with courses in business, technology, data, design, languages and personal development, and reports over 5.5 million active learners.', 'Courses', 'Online', 'Varies', 'Not stated', 'Open to learners. The site has a “free courses” section. Prices of other courses and certificates are not stated on the homepage.', null, false, true, 'https://www.rwaq.org/', array['arab','coding','languages','entrepreneurship']::text[], '2026-10-11'),
('kaust', 'KAUST Graduate Admissions', 'King Abdullah University of Science and Technology', 'The page describes KAUST as fully funded: over 90% of admitted students receive full tuition support, with a monthly stipend, housing, medical coverage and relocation help listed. Year-round faculty-led research internships and short AI and data courses are also listed.', 'Universities', 'In person', 'Funded', 'Graduate level (M.S., Ph.D., and a Master’s/Ph.D. pathway)', 'Entry requirements are on a separate KAUST page. Check it and the admissions timeline before applying.', null, true, true, 'https://admissions.kaust.edu.sa/', array['arab','research','science']::text[], '2026-10-11'),
('mbzuai', 'MBZUAI Admissions', 'Mohamed bin Zayed University of Artificial Intelligence', 'An AI-focused university in the UAE. The page lists undergraduate tuition at $45,000 per year plus cost of attendance, and says scholarships may cover tuition and costs and, in some packages, a stipend. Graduate funding depends on program and faculty.', 'Universities', 'In person', 'Varies', 'Undergraduate, Master’s and Ph.D.', 'No age limit and no SAT or ACT required. Undergraduate guideline: about 90% or higher overall and in Mathematics and STEM subjects. This does not guarantee admission. Recommendation letters, an English proficiency component and a screening exam are part of the process.', 'Not stated on the main page (check program pages). Fall 2027 starts mid-August 2027.', false, true, 'https://mbzuai.ac.ae/admissions/', array['arab','coding','science']::text[], '2026-10-11'),
('auc', 'The American University in Cairo (AUC)', 'AUC', 'Lists 35+ undergraduate degrees across four schools. The page says 64% of students receive scholarships or financial assistance, and some have full tuition coverage. It links to scholarships and Excellence Scholarships pages.', 'Universities', 'In person', 'Varies', 'Undergraduate and graduate', 'Requirements are on linked admissions pages, not the main page. The page also welcomes international and non-degree visiting students.', null, false, true, 'https://www.aucegypt.edu/admissions', array['arab','egypt']::text[], '2026-10-11'),
('zewail', 'Zewail City of Science, Technology and Innovation', 'Zewail City', 'Describes itself as Egypt’s premier institution for science and technology, in 6th of October City, Giza. It links to scholarships and tuition pages, research institutes and a Valley of Science and Technology.', 'Universities', 'In person', 'Not stated', 'Undergraduate and graduate', 'The homepage links to undergraduate, graduate, transfer and non-degree admissions, but does not state requirements or deadlines.', null, false, true, 'https://www.zewailcity.edu.eg/', array['arab','egypt','science','research']::text[], '2026-10-11'),
('ejust', 'Egypt-Japan University of Science and Technology (E-JUST)', 'E-JUST', 'A research university in Egypt with faculties of Engineering, Basic and Applied Science, International Business and Humanities, Computer Science and IT, Pharm D, and Art and Design. Housing is promoted for students from other Egyptian cities or Gulf countries.', 'Universities', 'In person', 'Not stated', 'Undergraduate and postgraduate', 'Admissions and scholarships are not described on the homepage. Check the university’s official pages.', null, false, true, 'https://www.ejust.edu.eg/', array['arab','egypt','science','coding']::text[], '2026-10-11'),
('nyuad', 'NYU Abu Dhabi Admissions', 'New York University Abu Dhabi', 'Lists undergraduate majors, minors and pre-professional courses, plus an MFA in Art and Media, MBA and EMBA with Stern, and PhD programs. The page says students come from more than 120 countries.', 'Universities', 'In person', 'Not stated', 'Undergraduate and graduate', 'The page does not list entry requirements. It links to How to Apply, Scholarships and Financial Aid, and Dates and Deadlines pages for undergraduates.', null, false, true, 'https://nyuad.nyu.edu/en/admissions.html', array['arab']::text[], '2026-10-11'),
('hungary', 'Stipendium Hungaricum Scholarship', 'Tempus Public Foundation (Hungary)', 'The page says scholarship holders have tuition fees covered and accommodation costs supported. It says applications for 2026/27 are open.', 'Scholarships', 'In person', 'Funded', 'Study programmes at Hungarian universities (levels not listed on the homepage)', 'The homepage does not state eligibility. See the call for applications linked from it.', null, false, true, 'https://stipendiumhungaricum.hu/', array['arab']::text[], '2026-10-11'),
('gates', 'Gates Cambridge Scholarship', 'University of Cambridge', 'An international scholarship at the University of Cambridge, established in 2000 with a gift from the Gates Foundation. Values listed: Community, Learning, Internationality, Compassion and Change.', 'Scholarships', 'In person', 'Not stated', 'Postgraduate students', 'The page describes it as for outstanding international postgraduate students who share a potential for social leadership. See the Eligibility and Timeline pages for details.', null, false, true, 'https://www.gatescambridge.org/apply/', array['research']::text[], '2026-10-11'),
('erasmus', 'Erasmus+ for Students', 'European Commission', 'Support for a study period abroad, traineeships abroad, and Erasmus Mundus Joint Master Degrees, which have scholarships available. Extra funding exists for students with physical, mental or health-related conditions. The page was last updated 13 September 2022.', 'Scholarships', 'In person', 'Varies', 'Short cycle, Bachelor, Master and Doctoral students', 'Traineeships need enrolment in higher education in a Programme country (recent graduates included). Deadlines, detailed criteria and amounts are on linked pages.', null, false, true, 'https://erasmus-plus.ec.europa.eu/opportunities/opportunities-for-individuals/students', array['languages']::text[], '2026-10-11'),
('mext', 'MEXT Scholarship (Japan)', 'Ministry of Education, Japan', 'A Japanese government program that supports foreign students who study in higher education institutions. What it covers is not stated on this page.', 'Scholarships', 'In person', 'Not stated', 'Foreign students in higher education institutions', 'The page says students are selected on the recommendation of a Japanese Embassy or Consulate General, a university, or an authority. It does not say if direct application is possible.', null, false, true, 'https://www.mext.go.jp/en/policy/education/highered/title02/detail02/sdetail02/1373897.htm', array['languages']::text[], '2026-10-11'),
('usembassy-eg', 'U.S. Embassy Cairo exchange programs', 'U.S. Embassy in Egypt', 'The Embassy says it offers Egyptians numerous opportunities to join short-term academic and professional programs in the United States.', 'Activities', 'In person', 'Not stated', 'Not stated', 'Requirements are not stated on this page. Open the exchange programs link from the embassy page.', null, false, true, 'https://eg.usembassy.gov/education-culture/', array['arab','egypt']::text[], '2026-10-11'),
('spaceapps', 'NASA International Space Apps Challenge', 'NASA', 'A hackathon on space and science. Teams use NASA and Space Agency Partner data to solve challenges written by NASA experts. The page lists 185+ countries and territories and 2,800+ local events over time.', 'Competitions', 'Not stated', 'Not stated', 'All ages and skill levels welcome', 'The page says all ages, skill levels and professional backgrounds are welcome. Next dates are not listed on the homepage.', null, false, true, 'https://www.spaceappschallenge.org/', array['science','coding']::text[], '2026-10-11'),
('hult', 'EF Hult Prize', 'Hult Prize Foundation', 'An annual student startup competition. The winning team receives 1 million USD in seed funding. The page lists 130+ participating countries.', 'Competitions', 'Not stated', 'Not stated', 'Students', 'Student competition. Stages, deadlines and criteria are not stated on the homepage.', null, false, true, 'https://hultprize.org/', array['entrepreneurship']::text[], '2026-10-11'),
('ipho', 'International Physics Olympiad (IPhO)', 'IPhO', 'Described as the most prestigious international physics competition for secondary school students, testing theoretical and experimental physics. IPhO 2026 is listed for Bucaramanga, Colombia, 4 to 12 July.', 'Competitions', 'In person', 'Not stated', 'Secondary school students (up to five per country)', 'National teams send their best physics students. The homepage does not describe how students qualify. Ask your national olympiad.', null, false, true, 'https://www.ipho-new.org/', array['science','math']::text[], '2026-10-11'),
('icho', 'International Chemistry Olympiad (IChO)', 'IChO Steering Committee', 'The 2027 Olympiad is listed for July 19 to 28 in Chinese Taipei, and 2028 for Messina, Italy.', 'Competitions', 'In person', 'Not stated', 'Not stated', 'Eligibility and qualification are not stated on the homepage. Ask your national chemistry olympiad.', 'IChO 2027: July 19-28, 2027', false, true, 'https://www.ichosc.org/', array['science']::text[], '2026-10-11'),
('ibo', 'International Biology Olympiad (IBO)', 'IBO', 'A high school biology competition. Dates and host of the next edition are not on the homepage.', 'Competitions', 'Not stated', 'Not stated', 'High school biology students (limits not stated)', 'The page says winners of national biology olympiads from more than 70 countries and regions take part. Ask your national olympiad.', null, false, true, 'https://www.ibo-info.org/', array['science','medicine']::text[], '2026-10-11'),
('odin', 'The Odin Project', 'The Odin Project', 'A free, open source web development curriculum built around hands-on projects, aimed at people who want to become full stack developers without a degree or coding school.', 'Courses', 'Online', 'Free', 'Any experience level', 'Open to anyone. Self-paced with a Discord community.', null, false, true, 'https://www.theodinproject.com/about', array['coding']::text[], '2026-10-11'),
('cs50ai', 'CS50 AI with Python', 'Harvard University', 'Seven weeks on the ideas behind modern AI: search, knowledge, uncertainty, optimization, learning, neural networks and language, with a Python project each week.', 'Courses', 'Online', 'Free', 'Needs CS50x or about a year of Python', 'Non-Harvard students can take the course free. Submitting projects for feedback needs an edX account. Certificates are paid, with fees not stated.', null, false, true, 'https://cs50.harvard.edu/ai/', array['coding','math']::text[], '2026-10-11'),
('fastai', 'fast.ai deep learning courses', 'fast.ai', 'Lists Practical Deep Learning for Coders and How to Solve it With Code among its courses.', 'Courses', 'Online', 'Not stated', 'Not stated', 'Prerequisites and current cost are not stated on the homepage. Older posts call earlier courses free.', null, false, true, 'https://www.fast.ai/', array['coding']::text[], '2026-10-11'),
('onlinevol', 'UN Online Volunteering', 'United Nations Volunteers', 'Connects organizations and volunteers to work on sustainable development challenges remotely. Sign-up takes a few minutes, per the page.', 'Volunteering', 'Online', 'Not stated', 'Age not stated', 'The page invites anyone with a computer, phone or tablet to volunteer. It lists no eligibility requirements.', null, false, true, 'https://www.onlinevolunteering.org/en', array['volunteering']::text[], '2026-10-11')
